mkuse!{use rustc_middle :: bug ;}
mkuse!{use rustc_middle :: ty :: { self , Const , DelayedMap , FallibleTypeFolder , InferConst , Ty , TyCtxt , TypeFoldable , TypeFolder , TypeSuperFoldable , TypeVisitableExt , } ;}
mkuse!{use super :: { FixupError , FixupResult , InferCtxt } ;}
mkuse!{use crate :: infer :: TyOrConstInferVar ;}
mkitem!{mkstruct!{# [doc = " The opportunistic resolver can be used at any time. It simply replaces"] # [doc = " type/const variables that have been unified with the things they have"] # [doc = " been unified with (similar to `shallow_resolve`, but deep). This is"] # [doc = " useful for printing messages etc but also required at various"] # [doc = " points for correctness."] pub struct OpportunisticVarResolver < 'a , 'tcx > { infcx : & 'a InferCtxt < 'tcx > , # [doc = " We're able to use a cache here as the folder does"] # [doc = " not have any mutable state."] cache : DelayedMap < Ty < 'tcx > , Ty < 'tcx > > , }}}
mkitem!{mkimpl!{impl < 'a , 'tcx > OpportunisticVarResolver < 'a , 'tcx > { # [inline] pub fn new (infcx : & 'a InferCtxt < 'tcx >) -> Self { OpportunisticVarResolver { infcx , cache : Default :: default () } } }}}
mkitem!{mkimpl!{impl < 'a , 'tcx > TypeFolder < TyCtxt < 'tcx > > for OpportunisticVarResolver < 'a , 'tcx > { fn cx (& self) -> TyCtxt < 'tcx > { self . infcx . tcx } # [inline] fn fold_ty (& mut self , t : Ty < 'tcx >) -> Ty < 'tcx > { if ! t . has_non_region_infer () { t } else if let Some (& ty) = self . cache . get (& t) { ty } else { let shallow = self . infcx . shallow_resolve (t) ; let res = shallow . super_fold_with (self) ; assert ! (self . cache . insert (t , res)) ; res } } fn fold_const (& mut self , ct : Const < 'tcx >) -> Const < 'tcx > { if ! ct . has_non_region_infer () { ct } else { let ct = self . infcx . shallow_resolve_const (ct) ; ct . super_fold_with (self) } } fn fold_predicate (& mut self , p : ty :: Predicate < 'tcx >) -> ty :: Predicate < 'tcx > { if ! p . has_non_region_infer () { p } else { p . super_fold_with (self) } } fn fold_clauses (& mut self , c : ty :: Clauses < 'tcx >) -> ty :: Clauses < 'tcx > { if ! c . has_non_region_infer () { c } else { c . super_fold_with (self) } } }}}
mkitem!{mkstruct!{# [doc = " The opportunistic region resolver opportunistically resolves regions"] # [doc = " variables to the variable with the least variable id. It is used when"] # [doc = " normalizing projections to avoid hitting the recursion limit by creating"] # [doc = " many versions of a predicate for types that in the end have to unify."] # [doc = ""] # [doc = " If you want to resolve type and const variables as well, call"] # [doc = " [InferCtxt::resolve_vars_if_possible] first."] pub struct OpportunisticRegionResolver < 'a , 'tcx > { infcx : & 'a InferCtxt < 'tcx > , }}}
mkitem!{mkimpl!{impl < 'a , 'tcx > OpportunisticRegionResolver < 'a , 'tcx > { pub fn new (infcx : & 'a InferCtxt < 'tcx >) -> Self { OpportunisticRegionResolver { infcx } } }}}
mkitem!{mkimpl!{impl < 'a , 'tcx > TypeFolder < TyCtxt < 'tcx > > for OpportunisticRegionResolver < 'a , 'tcx > { fn cx (& self) -> TyCtxt < 'tcx > { self . infcx . tcx } fn fold_ty (& mut self , t : Ty < 'tcx >) -> Ty < 'tcx > { if ! t . has_infer_regions () { t } else { t . super_fold_with (self) } } fn fold_region (& mut self , r : ty :: Region < 'tcx >) -> ty :: Region < 'tcx > { match r . kind () { ty :: ReVar (vid) => self . infcx . inner . borrow_mut () . unwrap_region_constraints () . opportunistic_resolve_var (TypeFolder :: cx (self) , vid) , _ => r , } } fn fold_const (& mut self , ct : ty :: Const < 'tcx >) -> ty :: Const < 'tcx > { if ! ct . has_infer_regions () { ct } else { ct . super_fold_with (self) } } }}}

macro_rules! fully_resolve_introspect {
    () => {
        emit_message!("📊 INTROSPECT: Function fully_resolve in module {}", module_path!());
    };
}

mkfn!{
    fully_resolve_introspect!();
    # [doc = " Full type resolution replaces all type and region variables with"] # [doc = " their concrete results. If any variable cannot be replaced (never unified, etc)"] # [doc = " then an `Err` result is returned."] pub fn fully_resolve < 'tcx , T > (infcx : & InferCtxt < 'tcx > , value : T) -> FixupResult < T > where T : TypeFoldable < TyCtxt < 'tcx > > , { value . try_fold_with (& mut FullTypeResolver { infcx }) }
}
mkitem!{mkstruct!{struct FullTypeResolver < 'a , 'tcx > { infcx : & 'a InferCtxt < 'tcx > , }}}
mkitem!{mkimpl!{impl < 'a , 'tcx > FallibleTypeFolder < TyCtxt < 'tcx > > for FullTypeResolver < 'a , 'tcx > { type Error = FixupError ; fn cx (& self) -> TyCtxt < 'tcx > { self . infcx . tcx } fn try_fold_ty (& mut self , t : Ty < 'tcx >) -> Result < Ty < 'tcx > , Self :: Error > { if ! t . has_infer () { Ok (t) } else { let t = self . infcx . shallow_resolve (t) ; match * t . kind () { ty :: Infer (ty :: TyVar (vid)) => { Err (FixupError { unresolved : TyOrConstInferVar :: Ty (vid) }) } ty :: Infer (ty :: IntVar (vid)) => { Err (FixupError { unresolved : TyOrConstInferVar :: TyInt (vid) }) } ty :: Infer (ty :: FloatVar (vid)) => { Err (FixupError { unresolved : TyOrConstInferVar :: TyFloat (vid) }) } ty :: Infer (_) => { bug ! ("Unexpected type in full type resolver: {:?}" , t) ; } _ => t . try_super_fold_with (self) , } } } fn try_fold_region (& mut self , r : ty :: Region < 'tcx >) -> Result < ty :: Region < 'tcx > , Self :: Error > { match r . kind () { ty :: ReVar (_) => Ok (self . infcx . lexical_region_resolutions . borrow () . as_ref () . expect ("region resolution not performed") . resolve_region (self . infcx . tcx , r)) , _ => Ok (r) , } } fn try_fold_const (& mut self , c : ty :: Const < 'tcx >) -> Result < ty :: Const < 'tcx > , Self :: Error > { if ! c . has_infer () { Ok (c) } else { let c = self . infcx . shallow_resolve_const (c) ; match c . kind () { ty :: ConstKind :: Infer (InferConst :: Var (vid)) => { return Err (FixupError { unresolved : super :: TyOrConstInferVar :: Const (vid) }) ; } ty :: ConstKind :: Infer (InferConst :: Fresh (_)) => { bug ! ("Unexpected const in full const resolver: {:?}" , c) ; } _ => { } } c . try_super_fold_with (self) } } }}}